/*
 * BIN 3.0 · comp "ABERTURA_v03" + 2 precomps
 * gerado em 07/11/2026 18:34
 *
 * cria as comps no projeto, com todas as layers.
 * File > Scripts > Run Script File...
 */
(function () {
	// ---- funções auxiliares do BIN (erros por propriedade não interrompem o script)
	var bin = {
		errors: [],
		err: function (what, e) { bin.errors.push(what + ': ' + (e && e.message ? e.message : e)); },
		path: function (p) {
			var n = [];
			try { while (p && p.parentProperty) { n.unshift(p.name); p = p.parentProperty; } } catch (e) { }
			return n.join(' > ');
		},
		add: function (g, mn, name) {
			if (!g) return null;
			var p;
			try { p = g.addProperty(mn); } catch (e) { bin.err('+ ' + mn, e); return null; }
			if (name) try { p.name = name; } catch (e2) { }
			return p;
		},
		attrs: function (o, a) {
			if (!o) return;
			for (var k in a) if (a.hasOwnProperty(k)) try { o[k] = a[k]; } catch (e) { bin.err((o.name || '') + '.' + k, e); }
		},
		shape: function (o) {
			var s = new Shape();
			s.vertices = o.v; s.inTangents = o.i; s.outTangents = o.o; s.closed = o.c;
			if (o.fs) {
				s.featherSegLocs = o.fs; s.featherRelSegLocs = o.ft; s.featherRadii = o.fr; s.featherInterps = o.fi;
				s.featherTensions = o.fn; s.featherTypes = o.fd; s.featherRelCornerAngles = o.fa;
			}
			return s;
		},
		doc: function (o) { o.__doc = true; return o; },
		// converte os valores marcados (textos) usando o documento atual da propriedade como base
		val: function (p, v) {
			if (!v || !v.__doc) return v;
			var d = p.value, k, q, r;
			var f = ['font', 'fontSize', 'applyFill', 'applyStroke', 'strokeWidth', 'strokeOverFill', 'justification', 'tracking', 'autoLeading',
				'baselineShift', 'horizontalScale', 'verticalScale', 'tsume', 'fauxBold', 'fauxItalic', 'allCaps', 'smallCaps', 'boxTextSize'];
			d.text = v.text;
			for (k = 0; k < f.length; k++) if (v[f[k]] !== undefined) try { d[f[k]] = v[f[k]]; } catch (e) { }
			if (v.applyFill && v.fillColor) try { d.fillColor = v.fillColor; } catch (e) { }
			if (v.applyStroke && v.strokeColor) try { d.strokeColor = v.strokeColor; } catch (e) { }
			if (!v.autoLeading && v.leading) try { d.leading = v.leading; } catch (e) { }
			if (v.runs && d.characterRange) {
				for (k = 0; k < v.runs.length; k++) {
					try {
						q = v.runs[k];
						r = d.characterRange(q.start, q.end);
						r.font = q.font; r.fontSize = q.fontSize; r.tracking = q.tracking;
						if (q.fillColor) r.fillColor = q.fillColor;
					} catch (e) { }
				}
			}
			return d;
		},
		set: function (p, v) {
			if (!p) return;
			try { p.setValue(bin.val(p, v)); } catch (e) { bin.err(bin.path(p), e); }
		},
		keys: function (p, keys) {
			if (!p) return;
			var I = { L: KeyframeInterpolationType.LINEAR, B: KeyframeInterpolationType.BEZIER, H: KeyframeInterpolationType.HOLD };
			var i, k, o;
			function ease(a) { var r = []; for (var n = 0; n < a.length; n++) r.push(new KeyframeEase(a[n][0], a[n][1])); return r; }
			try {
				while (p.numKeys > 0) p.removeKey(1); // ex.: o time remap já nasce com keys
				for (i = 0; i < keys.length; i++) p.setValueAtTime(keys[i].t, bin.val(p, keys[i].v));
			} catch (e) { bin.err(bin.path(p), e); return; }
			for (i = 0; i < keys.length; i++) {
				o = keys[i];
				k = p.nearestKeyIndex(o.t);
				if (o.i) try { p.setInterpolationTypeAtKey(k, I[o.i.charAt(0)], I[o.i.charAt(1)]); } catch (e) { }
				if (o.ta) try { p.setTemporalAutoBezierAtKey(k, true); } catch (e) { }
				else if (o.ei) try { p.setTemporalEaseAtKey(k, ease(o.ei), ease(o.eo)); } catch (e) { bin.err(bin.path(p) + ' (ease)', e); }
				if (o.tc) try { p.setTemporalContinuousAtKey(k, true); } catch (e) { }
				if (o.sa) try { p.setSpatialAutoBezierAtKey(k, true); } catch (e) { }
				else if (o.si) try { p.setSpatialTangentsAtKey(k, o.si, o.so); } catch (e) { }
				if (o.sc) try { p.setSpatialContinuousAtKey(k, true); } catch (e) { }
			}
			// roving só depois de todas as keys no lugar
			for (i = 0; i < keys.length; i++) if (keys[i].rv) try { p.setRovingAtKey(p.nearestKeyIndex(keys[i].t), true); } catch (e) { }
		},
		expr: function (p, x, on) {
			if (!p) return;
			try {
				p.expression = x;
				if (on === false) p.expressionEnabled = false;
			} catch (e) { bin.err(bin.path(p) + ' (expressão)', e); }
		},
		// markers de layer ou de comp
		marker: function (o, t, m) {
			try {
				var mv = new MarkerValue(m.comment || '');
				for (var k in m) if (m.hasOwnProperty(k) && k !== 'comment' && k !== 'params') try { mv[k] = m[k]; } catch (e) { }
				if (m.params) mv.setParameters(m.params);
				(o.markerProperty || o.property('ADBE Marker')).setValueAtTime(t, mv);
			} catch (e) { bin.err('marker ' + t, e); }
		},
		// precomp ou footage: procura no projeto pelo nome; se não achar, importa o arquivo ou cria um solid no lugar
		source: function (comp, o) {
			var item = null, i, it;
			for (i = 1; i <= app.project.numItems && !item; i++) {
				it = app.project.item(i);
				if (it.name === o.name && (o.kind === 'comp' ? it instanceof CompItem : it instanceof FootageItem) && it !== comp) item = it;
			}
			if (!item && o.file && new File(o.file).exists) try { item = app.project.importFile(new ImportOptions(new File(o.file))); } catch (e) { }
			if (item) return comp.layers.add(item);
			bin.err(o.name, 'item não encontrado no projeto: criado um solid no lugar');
			return comp.layers.addSolid([0.5, 0.5, 0.5], o.name + ' [faltando]', o.width || comp.width, o.height || comp.height, 1);
		},
		comp: function () {
			var c = app.project.activeItem;
			if (c instanceof CompItem) return c;
			alert('BIN: abra (ou selecione) a comp onde as layers serão criadas.');
			return null;
		},
		newComp: function (o, a) {
			var c = app.project.items.addComp(o.name, o.width, o.height, o.pixelAspect, o.duration, o.frameRate);
			if (a) bin.attrs(c, a);
			return c;
		},
		find: function (comp, name, made) {
			for (var i = 1; i <= comp.numLayers; i++) {
				var l = comp.layer(i), mine = false;
				for (var k in made) if (made[k] === l) mine = true;
				if (l.name === name && !mine) return l;
			}
			bin.err(name, 'layer não encontrada na comp');
			return null;
		},
		parent: function (l, p) {
			if (!l || !p) return;
			try {
				if (l.setParentWithJump) l.setParentWithJump(p); // mantém os valores de transform como estão
				else l.parent = p;
			} catch (e) { bin.err(l.name + ' > parent', e); }
		},
		matte: function (l, m, type) {
			if (!l) return;
			try {
				if (l.setTrackMatte && m) l.setTrackMatte(m, type); // AE 23+
				else l.trackMatteType = type;
			} catch (e) { bin.err(l.name + ' > track matte', e); }
		},
		// seleciona o que foi criado e deixa o resumo para o painel
		done: function (comp, made, comps) {
			var names = [], list = [], k, i;
			try {
				if (made) {
					for (i = 1; i <= comp.numLayers; i++) comp.layer(i).selected = false;
					for (k in made) if (made.hasOwnProperty(k) && made[k]) { made[k].selected = true; names.push(made[k].name); }
				}
				for (k in comps) if (comps.hasOwnProperty(k) && comps[k]) list.push(comps[k].name);
				comp.openInViewer();
			} catch (e) { }
			$.global.BIN_LAST = { ok: true, comp: comp ? comp.name : '', count: comp ? comp.numLayers : 0, layers: names, comps: list, errors: bin.errors };
			if (!$.global.BIN_PANEL && bin.errors.length) alert('BIN: ' + bin.errors.length + ' aviso(s)\n\n' + bin.errors.slice(0, 12).join('\n'));
		}
	};

	var C = {};

	// ==== comp PRE icone

	// bolinha (solid)
	function criar_bolinha(comp) {
		var layer = comp.layers.addSolid([1, 0.4, 0.2], 'bolinha', 200, 200, 1);
		bin.attrs(layer, { name: 'bolinha', label: 1 });

		// transform
		var transform = layer.property('ADBE Transform Group');
		bin.set(transform.property('ADBE Scale'), [40, 40, 100]);

		bin.attrs(layer, { inPoint: 0, outPoint: 5 });
		return layer;
	}

	// ==== comp PRE logo

	// PRE icone (precomp)
	function criar_pre_icone(comp) {
		var layer = comp.layers.add(C[1]);
		bin.attrs(layer, { name: 'PRE icone', label: 1 });

		// transform
		var transform = layer.property('ADBE Transform Group');
		bin.set(transform.property('ADBE Position'), [600, 200, 0]);

		bin.attrs(layer, { inPoint: 0, outPoint: 5 });
		return layer;
	}

	// circulo (shape)
	function criar_circulo(comp) {
		var layer = comp.layers.addShape();
		bin.attrs(layer, { name: 'circulo', label: 1 });

		// contents
		var contents = layer.property('ADBE Root Vectors Group');

		// Group 1
		var group1 = bin.add(contents, 'ADBE Vector Group', 'Group 1');
		var contents2 = group1.property('ADBE Vectors Group');
		var ellipsePath1 = bin.add(contents2, 'ADBE Vector Shape - Ellipse', 'Ellipse Path 1');
		bin.set(ellipsePath1.property('ADBE Vector Ellipse Size'), [300, 300]);

		bin.attrs(layer, { inPoint: 0, outPoint: 5 });
		return layer;
	}

	// ==== comp ABERTURA_v03

	// CTRL_titulo (null)
	function criar_ctrl_titulo(comp) {
		var layer = comp.layers.addNull();
		bin.attrs(layer, { name: 'CTRL_titulo', label: 2 });

		// transform
		var transform = layer.property('ADBE Transform Group');
		transform.property('ADBE Position').dimensionsSeparated = true;
		bin.set(transform.property('ADBE Position_0'), 900);
		bin.keys(transform.property('ADBE Position_1'), [
			{ t: 0, v: 500, i: 'LL' },
			{ t: 3, v: 560, i: 'LL' }
		]);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// MATTE (solid)
	function criar_matte(comp) {
		var layer = comp.layers.addSolid([1, 0, 0], 'MATTE', 1920, 1080, 1);
		bin.attrs(layer, { name: 'MATTE', label: 1 });

		// transform
		var transform = layer.property('ADBE Transform Group');
		bin.set(transform.property('ADBE Opacity'), 50);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// TITULO_principal (shape)
	function criar_titulo_principal(comp) {
		var layer = comp.layers.addShape();
		bin.attrs(layer, {
			name: 'TITULO_principal',
			label: 9,
			comment: 'vers\u00e3o "final" \u2014 n\u00e3o mexer'
		});

		// contents
		var contents = layer.property('ADBE Root Vectors Group');

		// Barra
		var barra = bin.add(contents, 'ADBE Vector Group', 'Barra');
		var contents2 = barra.property('ADBE Vectors Group');
		var rectanglePath1 = bin.add(contents2, 'ADBE Vector Shape - Rect', 'Rectangle Path 1');
		bin.keys(rectanglePath1.property('ADBE Vector Rect Size'), [
			{ t: 0, v: [0, 120], i: 'BB', ei: [[0, 33], [0, 33]], eo: [[0, 75], [0, 75]] },
			{ t: 0.5338, v: [860, 120], i: 'BL', ei: [[0, 16.6667], [0, 16.6667]], eo: [[0, 16.6667], [0, 16.6667]] }
		]);
		bin.set(rectanglePath1.property('ADBE Vector Rect Roundness'), 12);
		var fill1 = bin.add(contents2, 'ADBE Vector Graphic - Fill', 'Fill 1');
		bin.set(fill1.property('ADBE Vector Fill Color'), [0.298, 0.616, 1, 1]);
		var transform = barra.property('ADBE Vector Transform Group');
		bin.set(transform.property('ADBE Vector Position'), [10, -4]);

		// Estrela (off)
		var estrelaOff = bin.add(contents, 'ADBE Vector Group', 'Estrela (off)');
		estrelaOff.enabled = false;
		var contents3 = estrelaOff.property('ADBE Vectors Group');
		var path1 = bin.add(contents3, 'ADBE Vector Shape - Group', 'Path 1');
		bin.set(path1.property('ADBE Vector Shape'), bin.shape({ v: [[0, -50], [40, 30], [-40, 30]], i: [[0, 0], [0, 0], [0, 0]], o: [[0, 0], [5.5, 2], [0, 0]], c: true }));
		var stroke1 = bin.add(contents3, 'ADBE Vector Graphic - Stroke', 'Stroke 1');
		bin.set(stroke1.property('ADBE Vector Stroke Width'), 6);

		// transform
		var transform2 = layer.property('ADBE Transform Group');
		bin.keys(transform2.property('ADBE Position'), [
			{ t: 0, v: [960, 620, 0], i: 'LL' },
			{ t: 0.4, v: [960, 540, 0], i: 'BB', ei: [[0, 16.6667]], eo: [[0, 16.6667]], sc: true, rv: true, si: [-20, 0, 0], so: [20, 0, 0] },
			{ t: 5.6, v: [960, 460, 0], i: 'LL' }
		]);
		bin.keys(transform2.property('ADBE Scale'), [
			{ t: 0, v: [100, 100, 100], i: 'HH' },
			{ t: 2, v: [120, 120, 100], i: 'LL' }
		]);
		var rotation = transform2.property('ADBE Rotate Z');
		bin.set(rotation, 0);
		bin.expr(rotation, [
			'var amp = thisComp.layer("CONTROLE").effect("amp")("Slider");',
			'wiggle(2, amp);'
		].join('\n'));
		var opacity = transform2.property('ADBE Opacity');
		bin.set(opacity, 80);
		bin.expr(opacity, 'value * 0.5', false);

		// masks
		var masks = layer.property('ADBE Mask Parade');

		// recorte
		var recorte = bin.add(masks, 'ADBE Mask Atom', 'recorte');
		bin.attrs(recorte, { maskMode: MaskMode.SUBTRACT, inverted: true, color: [0.6, 0.6, 1] });
		bin.set(recorte.property('ADBE Mask Shape'), bin.shape({ v: [[0, 0], [1920, 0], [1920, 1080], [0, 1080]], i: [[0, 0], [0, 0], [0, 0], [0, 0]], o: [[0, 0], [0, 0], [0, 0], [0, 0]], c: true }));
		bin.set(recorte.property('ADBE Mask Feather'), [12, 12]);

		// effects
		var effects = layer.property('ADBE Effect Parade');

		// efeito › Glow
		var glow = bin.add(effects, 'ADBE Glo2', 'Glow');
		bin.set(glow.property('ADBE Glo2-0002'), 42);

		// efeito › Fill
		var fill = bin.add(effects, 'ADBE Fill', 'Fill');
		fill.enabled = false;
		bin.set(fill.property('ADBE Fill-0002'), [1, 1, 1, 1]);

		// markers
		bin.marker(layer, 0, { comment: 'entra', duration: 0.5, label: 3 });
		bin.marker(layer, 5.4, { comment: 'sai', duration: 0, chapter: 'cap 2', params: { fx: 'blur' } });

		bin.attrs(layer, {
			inPoint: 0.5,
			outPoint: 6.006,
			motionBlur: true,
			blendingMode: BlendingMode.ADD
		});
		return layer;
	}

	// CRÉDITO direção (text)
	function criar_credito_direcao(comp) {
		var layer = comp.layers.addBoxText([800, 200]);
		bin.attrs(layer, {
			name: 'CR\u00c9DITO dire\u00e7\u00e3o',
			label: 1,
			threeDLayer: true
		});

		// text
		var text = layer.property('ADBE Text Properties');
		bin.set(text.property('ADBE Text Document'), bin.doc({ text: 'Dire\u00e7\u00e3o\rANA BEATRIZ "Bia" D\'\u00c1vila', font: 'Inter-Bold', fontSize: 72, applyFill: true, applyStroke: false, strokeWidth: 1, strokeOverFill: false, tracking: 50, leading: 43.2, autoLeading: true, baselineShift: 0, horizontalScale: 1, verticalScale: 1, tsume: 0, fauxBold: false, fauxItalic: false, allCaps: false, smallCaps: false, boxText: true, justification: ParagraphJustification.CENTER_JUSTIFY, fillColor: [0.3, 0.62, 1], boxTextSize: [800, 200] }));
		var animators = text.property('ADBE Text Animators');

		// Fade
		var fade = bin.add(animators, 'ADBE Text Animator', 'Fade');
		var selectors = fade.property('ADBE Text Selectors');
		var rangeSelector1 = bin.add(selectors, 'ADBE Text Selector', 'Range Selector 1');
		bin.keys(rangeSelector1.property('ADBE Text Percent End'), [
			{ t: 0, v: 0, i: 'BB', ei: [[0, 75]], eo: [[0, 75]] },
			{ t: 1, v: 100, i: 'LL' }
		]);
		var properties = fade.property('ADBE Text Animator Properties');
		var opacity = bin.add(properties, 'ADBE Text Opacity');
		bin.set(opacity, 0);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// CONTROLE (adjustment)
	function criar_controle(comp) {
		var layer = comp.layers.addSolid([1, 1, 1], 'Adjustment Layer 1', 1920, 1080, 1);
		layer.adjustmentLayer = true;
		bin.attrs(layer, { name: 'CONTROLE', label: 1 });

		// effects
		var effects = layer.property('ADBE Effect Parade');

		// efeito › amp
		var amp = bin.add(effects, 'ADBE Slider Control', 'amp');
		bin.set(amp.property('ADBE Slider Control-0001'), 3);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// PRE logo (precomp)
	function criar_pre_logo(comp) {
		var layer = comp.layers.add(C[3]);
		bin.attrs(layer, {
			name: 'PRE logo',
			label: 1,
			startTime: 1.5
		});

		// transform
		var transform = layer.property('ADBE Transform Group');
		bin.set(transform.property('ADBE Scale'), [50, 50, 100]);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// Camera 1 (camera)
	function criar_camera_1(comp) {
		var layer = comp.layers.addCamera('Camera 1', [comp.width / 2, comp.height / 2]);
		bin.attrs(layer, { name: 'Camera 1', label: 1 });

		// camera options
		var cameraOptions = layer.property('ADBE Camera Options Group');
		bin.set(cameraOptions.property('ADBE Camera Zoom'), 2400);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// Luz (light)
	function criar_luz(comp) {
		var layer = comp.layers.addLight('Luz', [comp.width / 2, comp.height / 2]);
		bin.attrs(layer, { lightType: LightType.POINT });
		bin.attrs(layer, { name: 'Luz', label: 1 });

		// light options
		var lightOptions = layer.property('ADBE Light Options Group');
		bin.set(lightOptions.property('ADBE Light Intensity'), 150);

		bin.attrs(layer, { inPoint: 0, outPoint: 10 });
		return layer;
	}

	// comp PRE icone (precomp)
	function criar_comp_pre_icone() {
		var comp = bin.newComp({ name: 'PRE icone', width: 200, height: 200, pixelAspect: 1, duration: 5, frameRate: 29.97 }, { label: 15 });
		var L = {};
		L[1] = criar_bolinha(comp);
		return comp;
	}

	// comp PRE logo (precomp)
	function criar_comp_pre_logo() {
		var comp = bin.newComp({ name: 'PRE logo', width: 800, height: 800, pixelAspect: 1, duration: 5, frameRate: 29.97 }, {
			bgColor: [1, 1, 1],
			workAreaDuration: 3,
			workAreaStart: 1,
			label: 15
		});
		var L = {};
		L[2] = criar_circulo(comp);
		L[1] = criar_pre_icone(comp);

		// parentesco
		bin.parent(L[1], L[2]);
		return comp;
	}

	// comp ABERTURA_v03 (principal)
	function criar_comp_abertura_v03() {
		var comp = bin.newComp({ name: 'ABERTURA_v03', width: 1920, height: 1080, pixelAspect: 1, duration: 10, frameRate: 29.97 }, {
			bgColor: [0.05, 0.05, 0.08],
			motionBlur: true,
			shutterAngle: 270,
			label: 15
		});
		var L = {};
		L[8] = criar_luz(comp);
		L[7] = criar_camera_1(comp);
		L[6] = criar_pre_logo(comp);
		L[5] = criar_controle(comp);
		L[4] = criar_credito_direcao(comp);
		L[3] = criar_titulo_principal(comp);
		L[2] = criar_matte(comp);
		L[1] = criar_ctrl_titulo(comp);

		// parentesco
		bin.parent(L[3], L[1]);
		bin.parent(L[4], L[1]);

		// track matte
		bin.matte(L[3], L[2], TrackMatteType.ALPHA);

		L[1].locked = true;

		// markers da comp
		bin.marker(comp, 2, { comment: 'troca de cena', duration: 0 });
		return comp;
	}

	app.beginUndoGroup('BIN \u00b7 comp ABERTURA_v03');
	try {
		C[1] = criar_comp_pre_icone();
		C[3] = criar_comp_pre_logo();
		C[4] = criar_comp_abertura_v03();
	} catch (e) {
		bin.err('script', e);
	}
	app.endUndoGroup();
	bin.done(C[4], null, C);
})();
